<?phpclass MY_Pagination extends CI_Pagination {    /**     * Generate the pagination links that load pages asynchronously     *     * @param   string  $target     * @access  public     * @return     string     */    function create_links($formname = "form1") {        // If our item count or per-page total is zero there is no need to continue.        if (php72_cmp($this->total_rows) == 0 OR php72_cmp($this->per_page) == 0) {            return '';        }        // Calculate the total number of pages        $num_pages = ceil(php72_num($this->total_rows) / php72_num($this->per_page));        // Is there only one page? Hm... nothing more to do here then.        if ($num_pages == 1) {            return '';        }        // Determine the current page number.        $CI = & get_instance();        if ($CI->config->item('enable_query_strings') === TRUE OR $this->page_query_string === TRUE) {            if (php72_cmp($CI->input->get($this->query_string_segment)) != 0) {                $this->cur_page = $CI->input->get($this->query_string_segment);                // Prep the current page - no funny business!                $this->cur_page = (int) $this->cur_page;            }        } else {            if (php72_cmp($CI->uri->segment($this->uri_segment)) != 0) {                $this->cur_page = $CI->uri->segment($this->uri_segment);                // Prep the current page - no funny business!                $this->cur_page = (int) $this->cur_page;            }        }        $this->num_links = (int) $this->num_links;        if (php72_cmp($this->num_links) < 1) {            show_error('Your number of links must be a positive number.');        }        if (!is_numeric($this->cur_page)) {            $this->cur_page = 0;        }        // Is the page number beyond the result range?        // If so we show the last page        if ($this->cur_page > $this->total_rows) {            $this->cur_page = (php72_num($num_pages) - 1) * php72_num($this->per_page);        }        $uri_page_number = $this->cur_page;        $this->cur_page = floor((php72_num($this->cur_page) / php72_num($this->per_page)) + 1);        // Calculate the start and end numbers. These determine        // which number to start and end the digit links with        $start = (php72_cmp((php72_num($this->cur_page) - php72_num($this->num_links))) > 0) ? php72_num($this->cur_page) - (php72_num($this->num_links) - 1) : 1;        $end = ((php72_num($this->cur_page) + php72_num($this->num_links)) < $num_pages) ? php72_num($this->cur_page) + php72_num($this->num_links) : $num_pages;        // Is pagination being used over GET or POST?  If get, add a per_page query        // string. If post, add a trailing slash to the base URL if needed        if ($CI->config->item('enable_query_strings') === TRUE OR $this->page_query_string === TRUE) {            $this->base_url = rtrim($this->base_url) . '&amp;' . $this->query_string_segment . '=';        } else {            $this->base_url = rtrim($this->base_url, '/') . '/';        }        // And here we go...        $output = '';        // Render the "First" link        if ($this->cur_page > (php72_num($this->num_links) + 1)) {            $output .= $this->first_tag_open . "<a href=\"javascript:void(0);\" onclick=\"document." . $formname . ".action='" . $this->base_url . "';document." . $formname . ".submit();\">" . $this->first_link . "</a>" . $this->first_tag_close;        }        // Render the "previous" link        if (php72_cmp($this->cur_page) != 1) {            $i = php72_num($uri_page_number) - php72_num($this->per_page);            if (php72_cmp($i) == 0)                $i = '';            $output .= $this->prev_tag_open . "<a href=\"javascript:void(0);\"  onclick=\"document." . $formname . ".action='" . $this->base_url . $i . "';document." . $formname . ".submit();\">" . $this->prev_link . '</a>' . $this->prev_tag_close;        }        // Write the digit links        for ($loop = php72_num($start) - 1; $loop <= $end; $loop++) {            $i = (php72_num($loop) * php72_num($this->per_page)) - php72_num($this->per_page);            if (php72_cmp($i) >= 0) {                if ($this->cur_page == $loop) {                    $output .= $this->cur_tag_open . '<a href="javascript:void(0);" class="current" >' . $loop . '</a>' . $this->cur_tag_close; // Current page                } else {                    $n = (php72_cmp($i) == 0) ? '' : $i;                    $output .= $this->num_tag_open . "<a href=\"javascript:void(0);\"  onclick=\"document." . $formname . ".action='" . $this->base_url . $n . "';document." . $formname . ".submit();\">" . $loop . '</a>' . $this->num_tag_close;                }            }        }        // Render the "next" link        if ($this->cur_page < $num_pages) {            $output .= $this->next_tag_open . "<a href=\"javascript:void(0);\" onclick=\"document." . $formname . ".action='" . $this->base_url . (php72_num($this->cur_page) * php72_num($this->per_page)) . "';document." . $formname . ".submit();\">" . $this->next_link . '</a></li>' . $this->next_tag_close;        }        // Render the "Last" link        if ((php72_num($this->cur_page) + php72_num($this->num_links)) < $num_pages) {            $i = ((php72_num($num_pages) * php72_num($this->per_page)) - php72_num($this->per_page));            $output .= $this->last_tag_open . "<a href=\"javascript:void(0);\" onclick=\"document." . $formname . ".action='" . $this->base_url . $i . "';document." . $formname . ".submit();\">" . $this->last_link . '</a>' . $this->last_tag_close;        }        // Kill double slashes.  Note: Sometimes we can end up with a double slash        // in the penultimate link so we'll kill all double slashes.        $output = preg_replace("#([^:])//+#", "1/", $output);        // Add the wrapper HTML if exists        $output = '<div class="pagination">' . $output . '</div>';        return $output;    }    function create_links_new($formname = "form1") {        $page_number = php72_num($this->per_page) / 10;        // If our item count or per-page total is zero there is no need to continue.        if (php72_cmp($this->total_rows) == 0 OR php72_cmp($this->per_page) == 0) {            return '';        }        // Calculate the total number of pages        $num_pages = ceil(php72_num($this->total_rows) / php72_num($this->per_page));        // Is there only one page? Hm... nothing more to do here then.        if ($num_pages == 1) {            return '';        }        // Determine the current page number.        $CI = & get_instance();        if ($CI->config->item('enable_query_strings') === TRUE OR $this->page_query_string === TRUE) {            if (php72_cmp($CI->input->get($this->query_string_segment)) != 0) {                $this->cur_page = $CI->input->get($this->query_string_segment);                // Prep the current page - no funny business!                $this->cur_page = (int) $this->cur_page;            }        } else {            if (php72_cmp($CI->uri->segment($this->uri_segment)) != 0) {                $this->cur_page = $CI->uri->segment($this->uri_segment);                // Prep the current page - no funny business!                $this->cur_page = (int) $this->cur_page;            }        }        $this->num_links = (int) $this->num_links;        if (php72_cmp($this->num_links) < 1) {            show_error('Your number of links must be a positive number.');        }        if (!is_numeric($this->cur_page)) {            $this->cur_page = 0;        }        // Is the page number beyond the result range?        // If so we show the last page        if ($this->cur_page > $this->total_rows) {            $this->cur_page = (php72_num($num_pages) - 1) * php72_num($this->per_page);        }        $uri_page_number = $this->cur_page;        $this->cur_page = floor((php72_num($this->cur_page) / php72_num($this->per_page)) + 1);        // Calculate the start and end numbers. These determine        // which number to start and end the digit links with        $start = (php72_cmp((php72_num($this->cur_page) - php72_num($this->num_links))) > 0) ? php72_num($this->cur_page) - (php72_num($this->num_links) - 1) : 1;        $end = ((php72_num($this->cur_page) + php72_num($this->num_links)) < $num_pages) ? php72_num($this->cur_page) + php72_num($this->num_links) : $num_pages;        // Is pagination being used over GET or POST?  If get, add a per_page query        // string. If post, add a trailing slash to the base URL if needed        if ($CI->config->item('enable_query_strings') === TRUE OR $this->page_query_string === TRUE) {            $this->base_url = rtrim($this->base_url) . '&amp;' . $this->query_string_segment . '=';        } else {            $this->base_url = rtrim($this->base_url, '/') . '/';        }        // And here we go...        $output = '';        // Render the "First" link        if ($this->cur_page > (php72_num($this->num_links) + 1)) {            $output .= $this->first_tag_open . "<a href=\"javascript:void(0);\" onclick=\"document." . $formname . ".action='" . $this->base_url . "';document." . $formname . ".submit();\">" . $this->first_link . "</a>" . $this->first_tag_close;        }        // Render the "previous" link        if (php72_cmp($this->cur_page) != 1) {            $i = php72_num($uri_page_number) - php72_num($this->per_page);            if (php72_cmp($i) == 0)                $i = '';            $output .= $this->prev_tag_open . "<a href=\"javascript:void(0);\"  onclick=\"document." . $formname . ".action='" . $this->base_url . $i . "';document." . $formname . ".submit();\">" . $this->prev_link . '</a>' . $this->prev_tag_close;        }        // Write the digit links        for ($loop = php72_num($start) - 1; $loop <= $end; $loop++) {            $i = (php72_num($loop) * php72_num($this->per_page)) - php72_num($this->per_page);            if (php72_cmp($i) >= 0) {                if ($this->cur_page == $loop) {                    $output .= $this->cur_tag_open . '<a href="javascript:void(0);" class="current" >' . $loop . '</a>' . $this->cur_tag_close; // Current page                } else {                    $n = (php72_cmp($i) == 0) ? '' : $i;                    $output .= $this->num_tag_open . "<a href=\"javascript:void(0);\"  onclick=\"document." . $formname . ".action='" . $this->base_url . $n . "';document." . $formname . ".submit();\">" . $loop . '</a>' . $this->num_tag_close;                }            }        }        // Render the "next" link        if ($this->cur_page < $num_pages) {            $output .= $this->next_tag_open . "<a href=\"javascript:void(0);\" onclick=\"document." . $formname . ".action='" . $this->base_url . (php72_num($this->cur_page) * php72_num($this->per_page)) . "';document." . $formname . ".submit();\">" . $this->next_link . '</a></li>' . $this->next_tag_close;        }        // Render the "Last" link        if ((php72_num($this->cur_page) + php72_num($this->num_links)) < $num_pages) {            $i = ((php72_num($num_pages) * php72_num($this->per_page)) - php72_num($this->per_page));            $output .= $this->last_tag_open . "<a href=\"javascript:void(0);\" onclick=\"document." . $formname . ".action='" . $this->base_url . $i . "';document." . $formname . ".submit();\">" . $this->last_link . '</a>' . $this->last_tag_close;        }        // Kill double slashes.  Note: Sometimes we can end up with a double slash        // in the penultimate link so we'll kill all double slashes.        $output = preg_replace("#([^:])//+#", "1/", $output);        // Add the wrapper HTML if exists        $output = '<div class="pagination">' . $output . '</div>';        return $output;    }}?>